def reorganize_string(s):
    import heapq
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    heap = [(-n, c) for c, n in counts.items()]
    heapq.heapify(heap)
    out = []
    prev = None
    while heap or prev:
        if not heap:
            return ''
        n, c = heapq.heappop(heap)
        out.append(c)
        if prev:
            heapq.heappush(heap, prev)
        prev = (n + 1, c) if n + 1 else None
    return ''.join(out)
